// Uses the same bounded, hidden, BelowNormal transport fixture shared with the
// resident Checker packet. No daemon is started by an ordinary unit-test run.
#[path="../../../shared/test_native_transport.rs"]mod native_transport;
fn native_fix_daemon_pid(root:&Path)->u64{let mut rows=Vec::new();for entry in fs::read_dir(root.join("daemon/live")).unwrap(){let path=entry.unwrap().path();if path.extension()==Some(std::ffi::OsStr::new("json")){let value:serde_json::Value=serde_json::from_slice(&fs::read(path).unwrap()).unwrap();rows.push(value["pid"].as_u64().unwrap());}}assert_eq!(rows.len(),1);rows[0]}
fn native_fix_transport_report(bytes:&[u8],root:&Path,apply:bool)->(dq_analyze::native_fix_wire::Terminal,String){let newline=bytes.iter().position(|b|*b==b'\n').unwrap();let terminal:dq_analyze::native_fix_wire::Terminal=serde_json::from_slice(&bytes[..newline]).unwrap();terminal.require(root,&["code/probe.dm".into()],Codemod::Tracked,apply).unwrap();assert_eq!(terminal.selected,1);assert_eq!(terminal.visited,1);let payload=&bytes[newline+1..];let dn=terminal.diagnostics.as_ref().map_or(0,|s|s.length as usize);assert_eq!(payload.len(),dn+terminal.report.length as usize);if let Some(seal)=&terminal.diagnostics{assert_eq!(seal.hash.0,xxhash_rust::xxh3::xxh3_128(&payload[..dn]));}assert_eq!(terminal.report.hash.0,xxhash_rust::xxh3::xxh3_128(&payload[dn..]));let text=String::from_utf8(payload[dn..].to_vec()).unwrap();(terminal,text)}
#[test]#[ignore="private native IPC; run exact outside Cargo under dm_compile machine slot"]
fn actual_resident_native_fix_preview_apply_and_followup_reuse_one_daemon_and_seal_current_source(){
 use std::{ffi::OsStr,time::Duration};let f=fixture("resident-native-fix",BEFORE,false);let transport_root=scratch::dir("resident-native-fix-transport");let transport=native_transport::LibraryTransport{root:&transport_root,namespace:format!("resident-native-fix-{}",std::process::id())};let arguments=[OsStr::new("analyze-fix"),OsStr::new("--workspace"),f.root.as_os_str(),OsStr::new("--path"),OsStr::new("code/probe.dm")];let binary=Path::new(env!("CARGO_BIN_EXE_dmbc"));
 let first=transport.run_program_with_trace(binary,&arguments,Duration::from_secs(90),true).unwrap();assert_eq!(first.status.code(),Some(0),"{}",String::from_utf8_lossy(&first.stderr));assert!(first.stderr.is_empty());let(preview,text)=native_fix_transport_report(&first.stdout,&f.root,false);assert_eq!(preview.rewrites,1);assert_eq!(preview.committed_files,0);assert!(text.ends_with("1 rewrite(s) (dry run; --apply writes them), 0 for hand conversion\n"));assert_eq!(fs::read(f.root.join("code/probe.dm")).unwrap(),BEFORE.as_bytes());let pid=native_fix_daemon_pid(&transport_root);
 let mut apply=arguments.to_vec();apply.push(OsStr::new("--apply"));let second=transport.run_program(binary,&apply,Duration::from_secs(90)).unwrap();assert_eq!(second.status.code(),Some(0),"{}",String::from_utf8_lossy(&second.stderr));assert!(second.stderr.is_empty());let(applied,text)=native_fix_transport_report(&second.stdout,&f.root,true);assert_eq!(applied.committed_files,1);assert_eq!(applied.rewrites,1);assert!(text.ends_with("1 rewrite(s) applied, 0 for hand conversion\n"));assert_ne!(preview.frame.source_revision,applied.frame.source_revision);assert_eq!(fs::read(f.root.join("code/probe.dm")).unwrap(),AFTER.as_bytes());assert_eq!(native_fix_daemon_pid(&transport_root),pid);
 let third=transport.run_program(binary,&arguments,Duration::from_secs(90)).unwrap();assert_eq!(third.status.code(),Some(0),"{}",String::from_utf8_lossy(&third.stderr));let(after,_)=native_fix_transport_report(&third.stdout,&f.root,false);assert_eq!(after.rewrites,0);assert_eq!(after.committed_files,0);assert_eq!(native_fix_daemon_pid(&transport_root),pid);for entry in fs::read_dir(&f.root).unwrap(){assert!(!matches!(entry.unwrap().path().extension().and_then(|s|s.to_str()),Some("dmb"|"rsc")));}
}

fn batch_fixture(label:&str)->(Fixture,native_fix::BatchRequest){
 let f=full_fixture(label,"/obj/box/proc/probe()\r\n    count = 1\r\n",false);
 // Match the real generated-list-mutator boundary, not ordinary content:
 // those helpers intentionally write their own storage before publication.
 let definitions=fs::read_to_string(f.root.join("code/definitions.dm")).unwrap();let first=definitions.find("/obj/box/proc/add_items").unwrap();let scalar=definitions.find("/obj/box\n    var/count\n").unwrap();let insert=definitions.find("/obj/box/proc/insert_items").unwrap();assert!(first<scalar&&scalar<insert);let content=format!("{}{}",&definitions[..first],&definitions[scalar..insert]);let helpers=format!("{}{}",&definitions[first..scalar],&definitions[insert..]);put(&f.root,"code/definitions.dm",content);put(&f.root,"code/_generated/tracked_lists.dm",helpers);
 put(&f.root,"code/other.dm","/obj/box/proc/other()\r\n    count = 2\r\n");put(&f.root,"deepquarry.dme","#include \"code/definitions.dm\"\n#include \"code/_generated/auto_tracked.dm\"\n#include \"code/_generated/tracked_lists.dm\"\n#include \"code/probe.dm\"\n#include \"code/other.dm\"\n");let request=native_fix::BatchRequest{build:f.request.build.clone(),codemod:Codemod::Tracked,prefixes:Vec::new(),apply:true};(f,request)
}
#[test]fn actual_native_full_root_fix_batch_owns_roster_chains_real_reprepares_and_preserves_both_crlf_files(){
 let(f,mut request)=batch_fixture("native-full-root-fix-batch");let mut host=BuildHost::default();let(mut diagnostics,mut output)=(Vec::new(),Vec::new());let actual=native_fix::run_batch(request.clone(),&mut host,&mut diagnostics,&mut output).unwrap();assert_eq!(actual.selected,3,"actual CODE_MAPS_DM selected EOF includes definitions and two authored files, excludes generated marker");assert_eq!(actual.visited,actual.selected);assert_eq!(actual.committed_files,2);assert_eq!(actual.rewrites,2);assert_eq!(fs::read(f.root.join("code/probe.dm")).unwrap(),b"/obj/box/proc/probe()\r\n    set_count(1)\r\n");assert_eq!(fs::read(f.root.join("code/other.dm")).unwrap(),b"/obj/box/proc/other()\r\n    set_count(2)\r\n");drop(actual);request.apply=false;output.clear();let again=native_fix::run_batch(request,&mut host,&mut diagnostics,&mut output).unwrap();assert_eq!(again.selected,3);assert_eq!(again.visited,3);assert_eq!(again.rewrites,0);assert_eq!(again.committed_files,0);
}
struct ChangeBatchConfig{path:PathBuf,changed:bool,output:Vec<u8>}
impl Write for ChangeBatchConfig{fn write(&mut self,bytes:&[u8])->io::Result<usize>{if !self.changed{let bytes=fs::read(&self.path)?;let old=std::str::from_utf8(&bytes).map_err(io::Error::other)?;let changed=old.replace("# batch_marker_0","# batch_marker_1");assert_eq!(changed.len(),old.len());assert_ne!(changed,old);fs::write(&self.path,changed)?;self.changed=true;}self.output.extend_from_slice(bytes);Ok(bytes.len())}fn flush(&mut self)->io::Result<()>{Ok(())}}
#[test]fn actual_native_fix_batch_config_change_after_first_commit_refuses_completion_and_next_request_recovers(){
 let(f,mut request)=batch_fixture("native-batch-config-window");request.prefixes=vec!["code/other.dm".into(),"code/probe.dm".into()];let config=f.root.join("tools/ci/lint_scopes.toml");let mut bytes=fs::read(&config).unwrap();bytes.extend_from_slice(b"\n# batch_marker_0\n");fs::write(&config,bytes).unwrap();let mut sink=ChangeBatchConfig{path:config,changed:false,output:Vec::new()};let mut host=BuildHost::default();let mut diagnostics=Vec::new();let error=native_fix::run_batch(request.clone(),&mut host,&mut diagnostics,&mut sink).err().unwrap();assert!(sink.changed);let batch=error.downcast_ref::<native_fix::BatchFailure>().unwrap();assert_eq!(batch.committed_files,0,"the current failed attempt carries its own real commit evidence");use std::error::Error;assert!(batch.source().unwrap().downcast_ref::<CommittedFailure>().is_some());assert_eq!(fs::read(f.root.join("code/other.dm")).unwrap(),b"/obj/box/proc/other()\r\n    set_count(2)\r\n");assert_eq!(fs::read(f.root.join("code/probe.dm")).unwrap(),b"/obj/box/proc/probe()\r\n    count = 1\r\n");request.apply=false;let mut output=Vec::new();let healthy=native_fix::run_batch(request,&mut host,&mut diagnostics,&mut output).unwrap();assert_eq!(healthy.selected,2);assert_eq!(healthy.visited,2);assert_eq!(healthy.rewrites,1);assert_eq!(healthy.committed_files,0);
}
#[test]fn actual_native_fix_batch_first_output_io_after_commit_stays_primary_and_no_batch_receipt_is_issued(){
 use std::error::Error;let(f,mut request)=batch_fixture("native-batch-output-first-io");request.prefixes=vec!["code/other.dm".into(),"code/probe.dm".into()];let mut host=BuildHost::default();let mut diagnostics=Vec::new();let error=native_fix::run_batch(request.clone(),&mut host,&mut diagnostics,&mut StopOutput).err().unwrap();let batch=error.downcast_ref::<native_fix::BatchFailure>().unwrap();let committed=batch.source().unwrap().downcast_ref::<CommittedFailure>().unwrap();assert_eq!(committed.source().unwrap().downcast_ref::<io::Error>().unwrap().raw_os_error(),Some(1450));assert_eq!(fs::read(f.root.join("code/other.dm")).unwrap(),b"/obj/box/proc/other()\r\n    set_count(2)\r\n");assert_eq!(fs::read(f.root.join("code/probe.dm")).unwrap(),b"/obj/box/proc/probe()\r\n    count = 1\r\n");request.apply=false;let mut output=Vec::new();let healthy=native_fix::run_batch(request,&mut host,&mut diagnostics,&mut output).unwrap();assert_eq!(healthy.rewrites,1);assert_eq!(healthy.committed_files,0);
}

#[test]fn actual_native_fix_batch_unissued_body_is_incomplete_after_earlier_commit_not_residue_or_empty_success(){
 let(f,mut request)=batch_fixture("native-batch-unissued-body");put(&f.root,"code/z_unissued.dm","/obj/box/proc/z_unissued()\n    count = (1 + )\n");let manifest=fs::read_to_string(f.root.join("deepquarry.dme")).unwrap();put(&f.root,"deepquarry.dme",format!("{manifest}#include \"code/z_unissued.dm\"\n"));request.prefixes=vec!["code/other.dm".into(),"code/z_unissued.dm".into()];let mut host=BuildHost::default();let(mut diagnostics,mut output)=(Vec::new(),Vec::new());let error=native_fix::run_batch(request.clone(),&mut host,&mut diagnostics,&mut output).err().expect("a real missing completed BODY producer cannot become a successful residue-only/empty scan");let incomplete=error.downcast_ref::<native_fix::BatchFailure>().unwrap();assert_eq!(incomplete.committed_files,1);assert_eq!(fs::read(f.root.join("code/other.dm")).unwrap(),b"/obj/box/proc/other()\r\n    set_count(2)\r\n");assert_eq!(fs::read(f.root.join("code/z_unissued.dm")).unwrap(),b"/obj/box/proc/z_unissued()\n    count = (1 + )\n");assert!(!String::from_utf8_lossy(&output).ends_with("1 rewrite(s) applied, 0 for hand conversion\n"),"no whole-batch summary is issued on missing producer");drop(error);
 put(&f.root,"code/z_unissued.dm","/obj/box/proc/z_unissued()\n    count = 3\n");request.apply=false;output.clear();let recovered=native_fix::run_batch(request,&mut host,&mut diagnostics,&mut output).unwrap();assert_eq!(recovered.visited,2);assert_eq!(recovered.rewrites,1);assert_eq!(recovered.committed_files,0);
}

#[test]fn actual_native_fix_batch_oversized_binding_refuses_before_any_source_mutation(){
 let(f,mut request)=batch_fixture("native-batch-oversized-binding");let before=fs::read(f.root.join("code/other.dm")).unwrap();request.prefixes=vec![format!("code/{}", "x".repeat(2048))];let mut host=BuildHost::default();let(mut diagnostics,mut output)=(Vec::new(),Vec::new());let error=native_fix::run_batch(request,&mut host,&mut diagnostics,&mut output).err().expect("oversized real JSON binding must refuse before mutation");assert!(error.to_string().contains("header"),"{error}");assert_eq!(fs::read(f.root.join("code/other.dm")).unwrap(),before);assert!(diagnostics.is_empty()&&output.is_empty());
}
